// glass-ui 10.1.5 — critic round 12 probe harness, the v10.1.4 arm (imports from v1014/). Reads only.
// imports pointed at `v1014/` (critic-12-v1014.ts, generated by sed).
// Scenes:
//   `atoms`  INBOUND O-207 G3 the atoms critique 11 did not walk: a default Slider (its ring is on the
//            track), a spectrum Slider (its ring is on the thumb), a SortableList handle.
//   `sheet`  INBOUND O-207 K4: an open bottom Sheet with detents (its "Sheet position" handle).
// `?dark=1` sets the theme.
import "./v1014/demo/demo.css";
import { createApp, defineComponent, h, ref, type Component } from "vue";

import Slider from "./v1014/src/components/slider/Slider.vue";
import { SortableList, SortableItem, SortableHandle } from "./v1014/src/components/sortable-list";
import { Dialog, DialogTitle, DialogDescription } from "./v1014/src/components/dialog";
import { SheetContent } from "./v1014/src/components/sheet";

const params = new URLSearchParams(location.search);
const scene = params.get("scene") ?? "";
const w = window as unknown as Record<string, unknown>;
try {
    localStorage.setItem("vueuse-color-scheme", params.get("dark") === "1" ? "dark" : "light");
} catch {}
if (params.get("dark") === "1") document.documentElement.classList.add("dark");

const scenes: Record<string, Component> = {
    atoms: defineComponent(() => {
        const a = ref([40]);
        const b = ref([40]);
        const items = ref([{ id: "a", label: "Alpha" }, { id: "b", label: "Beta" }]);
        return () =>
            h("div", { "data-witness": "stage", style: "display:grid;gap:28px;padding:32px;max-inline-size:520px" }, [
                h("div", { "data-witness": "slider" }, h(Slider, { modelValue: a.value, "onUpdate:modelValue": (x: number[]) => (a.value = x), min: 0, max: 100, "aria-label": "Default" })),
                h("div", { "data-witness": "spectrum" }, h(Slider, { variant: "spectrum", modelValue: b.value, "onUpdate:modelValue": (x: number[]) => (b.value = x), min: 0, max: 100, "aria-label": "Spectrum" })),
                h("div", { "data-witness": "sortable" },
                    h(SortableList, { items: items.value, getId: (t: { id: string }) => t.id, getLabel: (t: { label: string }) => t.label, "onUpdate:items": (v: typeof items.value) => (items.value = v) }, () =>
                        items.value.map((t) => h(SortableItem, { key: t.id, id: t.id }, () => [h(SortableHandle, null, () => h("span", "::")), h("span", t.label)])),
                    ),
                ),
            ]);
    }),
    sheet: defineComponent(() => () =>
        h(Dialog, { defaultOpen: true }, () =>
            h(SheetContent, { side: "bottom", detents: [0.4, 0.9] }, () => [h(DialogTitle, null, () => "Sheet"), h(DialogDescription, null, () => "detented")]),
        ),
    ),
};

const Scene = scenes[scene];
if (!Scene) throw new Error(`unknown scene "${scene}"`);
createApp(Scene).mount("#app");
w.__ready = true;
